'use strict';

const fs = require('node:fs');
const path = require('node:path');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const INPUT_FILE = 'config.json';
const OUTPUT_FILE = 'config.out.json';

function readConfig(file) {
  if (!fs.existsSync(file)) {
    return {};
  }
  const raw = fs.readFileSync(file, 'utf8');
  if (raw.trim() === '') {
    return {};
  }
  return JSON.parse(raw);
}

function applyDefaults(config) {
  const merged = { ...config };
  for (const [key, fallback] of Object.entries(DEFAULTS)) {
    if (merged[key] === undefined || merged[key] === null) {
      merged[key] = fallback;
    }
  }
  return merged;
}

function main() {
  const root = __dirname;
  const inputPath = path.join(root, INPUT_FILE);
  const outputPath = path.join(root, OUTPUT_FILE);

  const config = applyDefaults(readConfig(inputPath));
  fs.writeFileSync(outputPath, `${JSON.stringify(config, null, 2)}\n`, 'utf8');

  console.log(`read     ${INPUT_FILE}: ${JSON.stringify(readConfig(inputPath))}`);
  console.log(`defaults ${JSON.stringify(DEFAULTS)}`);
  console.log(`wrote    ${OUTPUT_FILE}: ${JSON.stringify(config)}`);
}

main();

